const lessons=[{"sentences":[{"speaker":"A","text":"Welcome to the student village orientation session for all new residents living on campus.","position":1,"audioStartSeconds":0,"audioEndSeconds":5.894166666666667},{"speaker":"A","text":"My name is Sarah and I manage the accommodation services office for the university.","position":2,"audioStartSeconds":6.094166666666666,"audioEndSeconds":11.455791666666666},{"speaker":"A","text":"Today I will explain our shared facilities and how you can report maintenance problems.","position":3,"audioStartSeconds":11.655791666666667,"audioEndSeconds":17.05525},{"speaker":"A","text":"Every floor has a shared kitchen where students can cook meals together every evening.","position":4,"audioStartSeconds":17.25525,"audioEndSeconds":22.435666666666666},{"speaker":"A","text":"You must wash your dishes immediately after cooking and keep the counter clean.","position":5,"audioStartSeconds":22.635666666666665,"audioEndSeconds":27.403708333333334},{"speaker":"A","text":"Next to the kitchen you will find the laundry room with four modern washing machines.","position":6,"audioStartSeconds":27.603708333333334,"audioEndSeconds":32.500625},{"speaker":"A","text":"Each wash cycle costs two pounds and you need contactless payment cards to operate them.","position":7,"audioStartSeconds":32.700625,"audioEndSeconds":38.164541666666665},{"speaker":"A","text":"Outside the main building we have a secure bicycle shed for daily commuters.","position":8,"audioStartSeconds":38.36454166666667,"audioEndSeconds":43.30008333333333},{"speaker":"A","text":"You should register your bicycle at my office to receive a parking sticker.","position":9,"audioStartSeconds":43.500083333333336,"audioEndSeconds":48.06195833333334},{"speaker":"A","text":"If something breaks in your room or kitchen you must submit an online repair form.","position":10,"audioStartSeconds":48.26195833333333,"audioEndSeconds":53.22329166666667},{"speaker":"A","text":"Never try to fix electrical appliances yourself because this creates serious safety hazards.","position":11,"audioStartSeconds":53.423291666666664,"audioEndSeconds":59.27379166666667},{"speaker":"A","text":"For urgent emergencies during the night please contact the campus security guard directly.","position":12,"audioStartSeconds":59.47379166666666,"audioEndSeconds":65.32433333333333},{"speaker":"A","text":"Thank you for listening and I hope you enjoy living in our friendly community.","position":13,"audioStartSeconds":65.52433333333333,"audioEndSeconds":70.14508333333333}],"questions":[{"prompt":"Kitchen location: on each ______","answer":"floor","evidenceSentence":4,"evidence":"Every floor has a shared kitchen","explanation":"Người nói cho biết nhà bếp chung nằm ở mỗi tầng."},{"prompt":"Washing machine cost: ______ pounds","answer":"two","evidenceSentence":7,"evidence":"Each wash cycle costs two pounds","explanation":"Chi phí cho mỗi lần giặt là hai bảng."},{"prompt":"Payment method: ______ cards","answer":"contactless","evidenceSentence":7,"evidence":"you need contactless payment cards","explanation":"Bạn cần dùng thẻ thanh toán không tiếp xúc."},{"prompt":"Bicycle storage location: secure ______","answer":"bicycle shed","evidenceSentence":8,"evidence":"we have a secure bicycle shed","explanation":"Khu vực để xe đạp an toàn nằm ở bên ngoài tòa nhà chính."},{"prompt":"Repair request method: online ______","answer":"repair form","evidenceSentence":10,"evidence":"you must submit an online repair form","explanation":"Bạn phải gửi biểu mẫu sửa chữa trực tuyến khi có hỏng hóc."},{"prompt":"Night emergency contact: security ______","answer":"guard","evidenceSentence":12,"evidence":"please contact the campus security guard","explanation":"Vào ban đêm, hãy liên hệ với nhân viên bảo vệ khuôn viên trường."}]}];const cards=[...document.querySelectorAll('article')];let stopping=null,stoppingAudio=null;
    document.addEventListener('play',event=>{if(event.target.tagName!=='AUDIO')return;document.querySelectorAll('audio').forEach(a=>{if(a!==event.target)a.pause()})},true);
    document.querySelectorAll('[data-filter]').forEach(button=>button.onclick=()=>{let count=0;cards.forEach(c=>{c.hidden=button.dataset.filter!=='ALL'&&c.dataset.goal!==button.dataset.filter;if(!c.hidden)count++;else c.querySelector('audio').pause()});document.querySelectorAll('[data-filter]').forEach(b=>b.setAttribute('aria-pressed',b===button));document.querySelector('#filter-status').textContent='Đang hiển thị '+count+' bài.'});
    const normal=value=>value.trim().toLowerCase().replace(/\s+/g,' ');
    document.querySelectorAll('[data-check]').forEach(button=>button.onclick=()=>{const i=Number(button.dataset.check);let score=0;lessons[i].questions.forEach((q,n)=>{const value=normal(document.getElementById('answer-'+i+'-'+n).value);if([q.answer,...(q.accepted||[])].some(a=>normal(a)===value))score++});document.getElementById('result-'+i).textContent=score+'/'+lessons[i].questions.length+' câu đúng. Mở phần đáp án để xem giải thích.'});
    document.querySelectorAll('[data-segment]').forEach(button=>button.onclick=async()=>{if(stopping)stopping();const [i,n]=button.dataset.segment.split(',').map(Number),audio=cards[i].querySelector('audio'),s=lessons[i].sentences[n];audio.currentTime=s.audioStartSeconds;const stop=()=>{stopping=null;stoppingAudio=null;audio.removeEventListener('timeupdate',check);audio.pause()},check=()=>{if(audio.currentTime>=s.audioEndSeconds)stop()};stopping=stop;stoppingAudio=audio;audio.addEventListener('timeupdate',check);try{await audio.play()}catch(_){stop();document.getElementById('result-'+i).textContent='Không phát được audio. Hãy dùng nút tải WAV để nghe.'}});
    document.querySelectorAll('audio').forEach(audio=>audio.addEventListener('pause',()=>{if(audio.paused&&stoppingAudio===audio&&stopping)stopping()}));
const authStatus=document.querySelector('#auth-status');
async function initializeAudio(){
 try{
  const response=await fetch('/api/auth/me',{credentials:'same-origin'});
  if(response.status===401){authStatus.hidden=false;authStatus.innerHTML='Đăng nhập để nghe audio. <a href="/login?next=%2Fcatalog%3Fgoal%3DALL">Đăng nhập</a> rồi mở bài từ thư viện bằng nút “Nghe toàn bài & làm câu hỏi”.';return}
  if(!response.ok)throw Error('account');
  document.querySelectorAll('audio').forEach(audio=>{audio.src=audio.dataset.src;audio.preload='none';audio.hidden=false});
  document.querySelectorAll('[data-segment]').forEach(button=>button.disabled=false);
  document.querySelectorAll('a[download]').forEach(link=>link.hidden=false);
 }catch(_){authStatus.hidden=false;authStatus.textContent='Không kiểm tra được đăng nhập. Hãy tải lại trang để thử lại.'}
}
initializeAudio();
